const input = $json ?? {};
const execution =
  input.execution && typeof input.execution === 'object'
    ? input.execution
    : {};
const workflow =
  input.workflow && typeof input.workflow === 'object'
    ? input.workflow
    : {};
const error =
  execution.error && typeof execution.error === 'object'
    ? execution.error
    : (
        input.error && typeof input.error === 'object'
          ? input.error
          : {}
      );

const componentByWorkflow = {
  REVINTV2RESTINGEST01: 'rest_ingestion',
  REVINTV2AGENTCORE01: 'agent_reporting',
  REVINTV2SCHEDULED01: 'scheduled_intelligence',
  REVINTV2OBS01: 'observability',
  REVINTV2HUBSPOT01: 'hubspot_sync',
  REVINTV2SALESFORCE01: 'salesforce_sync',
  REVINTV2AIRTABLE01: 'airtable_sync',
};

const workflowId = String(
  workflow.id ?? input.workflowId ?? input.workflow_id ?? ''
).trim();

const redact = value => {
  let text = String(value ?? 'Unknown workflow failure');
  text = text
    .replace(/(authorization\s*:\s*bearer\s+)[^\s]+/ig, '$1[REDACTED]')
    .replace(/((?:password|passwd|token|api[_-]?key|secret)\s*[=:]\s*)[^\s,;]+/ig, '$1[REDACTED]');
  return text.replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 1000);
};

const statusCandidates = [
  error.httpStatus,
  error.httpCode,
  error.statusCode,
  error.status,
  error.response?.status,
  error.cause?.statusCode,
];
let httpStatus = null;
for (const candidate of statusCandidates) {
  const parsed = Number(candidate);
  if (Number.isInteger(parsed) && parsed >= 100 && parsed <= 599) {
    httpStatus = parsed;
    break;
  }
}

const occurredRaw = error.timestamp ?? input.timestamp ?? null;
const occurred = occurredRaw ? new Date(occurredRaw) : new Date();
const occurredAt = Number.isNaN(occurred.getTime())
  ? new Date().toISOString()
  : occurred.toISOString();

return {
  failure_context: {
    component_key: componentByWorkflow[workflowId] ?? 'unmanaged',
    workflow_id: workflowId,
    workflow_name: String(workflow.name ?? input.workflowName ?? 'Unknown Workflow').slice(0, 200),
    execution_id: String(execution.id ?? input.executionId ?? input.execution_id ?? '').slice(0, 200),
    retry_of_execution_id: execution.retryOf == null ? null : String(execution.retryOf).slice(0, 200),
    node_name: String(execution.lastNodeExecuted ?? error.node?.name ?? error.nodeName ?? 'Unknown Node').slice(0, 200),
    error_name: error.name == null ? null : String(error.name).slice(0, 200),
    error_code: error.code == null ? null : String(error.code).slice(0, 200),
    error_message: redact(error.message ?? error.description ?? input.message),
    http_status: httpStatus,
    occurred_at: occurredAt
  },
  workflow_stage: 'terminal_failure_normalized'
};
